    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'");
}

export function toPythonRepr(value) {
  if (typeof value === 'string') {
    return `'${escapePythonString(value)}'`;
  }

  if (typeof value === 'number') {
    return String(value);
  }

  if (typeof value === 'boolean') {
    return value ? 'True' : 'False';
  }

  if (value === null) {
    return 'None';
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => toPythonRepr(item)).join(', ')}]`;
  }

  if (typeof value === 'object') {
    return `{${Object.entries(value)
      .map(([key, item]) => `${toPythonRepr(key)}: ${toPythonRepr(item)}`)
      .join(', ')}}`;
  }

  return String(value);
}

