import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(keyBytes, messageBytes) {
  let normalizedKey = keyBytes;

  if (normalizedKey.length > BLOCK_SIZE) {
    normalizedKey = sha256(normalizedKey);
  }

  const keyBlock = new Uint8Array(BLOCK_SIZE);
  keyBlock.set(normalizedKey);

  const innerPad = new Uint8Array(BLOCK_SIZE);
  const outerPad = new Uint8Array(BLOCK_SIZE);

  for (let index = 0; index < BLOCK_SIZE; index += 1) {
    innerPad[index] = keyBlock[index] ^ 0x36;
    outerPad[index] = keyBlock[index] ^ 0x5c;
  }

  const innerDigest = sha256(concatBytes(innerPad, messageBytes));
  return sha256(concatBytes(outerPad, innerDigest));
}

