export function encodeBase64UrlBytes(bytes) {
  return Buffer.from(bytes)
    .toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/g, '');
}

export function encodeBase64UrlUtf8(text) {
  return encodeBase64UrlBytes(toUtf8Bytes(text));
}

export function decodeBase64UrlToBytes(text) {
  const normalized = text.replace(/-/g, '+').replace(/_/g, '/');
  const paddingLength = (4 - (normalized.length % 4)) % 4;
  return Uint8Array.from(Buffer.from(normalized + '='.repeat(paddingLength), 'base64'));
}

export function decodeBase64UrlToUtf8(text) {
  return fromUtf8Bytes(decodeBase64UrlToBytes(text));
}

