import {
  decodeBase64UrlToBytes,
  decodeBase64UrlToUtf8,
  encodeBase64UrlBytes,
  encodeBase64UrlUtf8,
} from './base64url.mjs';
import { equalBytes, toUtf8Bytes } from './bytes.mjs';
import { hmacSha256 } from './hmac.mjs';

function parseJson(text, label) {
  try {
    return JSON.parse(text);
  } catch {
    throw new Error(`Invalid ${label}`);
  }
}

function validateIssuedAt(payload) {
  if (!Object.prototype.hasOwnProperty.call(payload, 'iat')) {
    return;
  }

  const issuedAt = payload.iat;

  if (typeof issuedAt !== 'number' || !Number.isFinite(issuedAt) || !Number.isInteger(issuedAt)) {
    throw new Error('Issued At claim (iat) must be an integer.');
  }

  if (issuedAt > Math.floor(Date.now() / 1000)) {
    throw new Error('The token is not yet valid (iat)');
  }
}

export function encodeJwt(payload, secret) {
  const headerSegment = encodeBase64UrlUtf8(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const payloadSegment = encodeBase64UrlUtf8(JSON.stringify(payload));
  const signingInput = `${headerSegment}.${payloadSegment}`;
  const signature = hmacSha256(toUtf8Bytes(secret), toUtf8Bytes(signingInput));

  return `${signingInput}.${encodeBase64UrlBytes(signature)}`;
}

export function decodeJwt(token, secret, options = {}, algorithms = []) {
  const parts = token.split('.');

  if (parts.length !== 3 || parts.some((part) => part.length === 0)) {
    throw new Error('Not enough segments');
  }

  const [headerSegment, payloadSegment, signatureSegment] = parts;
  const header = parseJson(decodeBase64UrlToUtf8(headerSegment), 'header');

  if (!algorithms.includes(header.alg)) {
    throw new Error('The specified alg value is not allowed');
  }

  const signingInput = `${headerSegment}.${payloadSegment}`;
  const expectedSignature = hmacSha256(toUtf8Bytes(secret), toUtf8Bytes(signingInput));
  const actualSignature = decodeBase64UrlToBytes(signatureSegment);

  if (!equalBytes(actualSignature, expectedSignature)) {
    throw new Error('Signature verification failed');
  }

  const payload = parseJson(decodeBase64UrlToUtf8(payloadSegment), 'payload');

  if (options.verify_iat) {
    validateIssuedAt(payload);
  }

  return payload;
}

