import {
  ArgparseError,
  buildErrorText,
  buildHelpText,
  getProgramName,
  parseCommandLine,
} from './lib/argparse_like.mjs';
import { decodeJwt, encodeJwt } from './lib/jwt.mjs';
import { toPythonRepr } from './lib/python_repr.mjs';

export function main(argv = process.argv) {
  const programName = getProgramName(argv);
  let args;

  try {
    args = parseCommandLine(argv.slice(2));
  } catch (error) {
    if (error instanceof ArgparseError) {
      process.stderr.write(buildErrorText(programName, error.message));
      return 2;
    }

    throw error;
  }

  if (args.help) {
    process.stdout.write(buildHelpText(programName));
    return 0;
  }

  const secret = 'secret';
  const payload = {
    info: args.data,
    iat: Math.floor(Date.now() / 1000),
  };
  const token = encodeJwt(payload, secret);

  process.stdout.write(`${token}\n`);

  const verifyIat = args.verify_iat === 'true';
  const decoded = decodeJwt(token, secret, { verify_iat: verifyIat }, ['HS256']);

  process.stdout.write(`${toPythonRepr(decoded)}\n`);
  return 0;
}

